  @api cmgr:keyLabel(spec, ImGui)  @ 589-601
  @api cmgr:keyLabelList(name, ImGui)  @ 604-610
      @contract  list of human labels, one per bound keyspec of the reachable command, or nil if unbound  @ 603
  @api cmgr:keyLabels(name, ImGui)  @ 613-616
      @contract  keyLabelList joined by ' / ', or nil if unbound on the current stack  @ 612
  @api cmgr:tokenForSpec(spec, ImGui)  @ 678-689
      @contract  spec -> stable ASCII token ("Ctrl+Z"); nil if the key has no token name  @ 677
  @api cmgr:specForToken(token, ImGui)  @ 692-707
      @contract  token -> keyspec (bare key | {key, mod...}); (nil, err) on an unknown key/modifier  @ 691
  @api cmgr:loadOverrides(ImGui)  @ 713-728
      @contract  a malformed token is warned and skipped; the command keeps its other (good) bindings  @ 712
  @api cmgr:rebind(scopeName, name, specs, ImGui)  @ 731-741
      @contract  overwrites the scope's binding for name and persists it as tokens (global tier)  @ 730
  @api cmgr:familyVictim(family, mods, ImGui)  @ 764-775
      @contract  (victim, spec) for the first proposed chord already spoken for; nil if the mask is free  @ 762
      @invariant  a family's own members are never victims — a rebind vacates their chords wholesale  @ 763
  @api cmgr:rebindFamily(family, mods, ImGui)  @ 778-782
      @contract  rewrites every member to its base token under mods, one binding each, live + persisted  @ 777

